package com.hmdp.ai.application.observability;import com.hmdp.ai.application.dto.observability.*;import com.hmdp.ai.application.security.AiAccessGuard;import com.hmdp.ai.domain.observability.*;import com.hmdp.ai.domain.run.RunRepository;import com.hmdp.ai.domain.security.*;import java.util.*;import java.util.function.BiFunction;import java.util.stream.Collectors;import org.springframework.stereotype.Service;
@Service public class RunInspectionApplicationService {private final RunInspectionPort inspection;private final RunRepository runs;private final AiAccessGuard access;public RunInspectionApplicationService(RunInspectionPort inspection,RunRepository runs,AiAccessGuard access){this.inspection=inspection;this.runs=runs;this.access=access;}public List<RunInspectionItemResponse>nodes(String id){return items(id,(t,w)->inspection.nodeRuns(t,w,id));}public List<RunInspectionItemResponse>models(String id){return items(id,(t,w)->inspection.modelCalls(t,w,id));}public List<RunInspectionItemResponse>tools(String id){return items(id,(t,w)->inspection.toolCalls(t,w,id));}public List<RunInspectionItemResponse>retrievals(String id){return items(id,(t,w)->inspection.retrievals(t,w,id));}public List<RunInspectionItemResponse>artifacts(String id){return items(id,(t,w)->inspection.artifacts(t,w,id));}public RunUsageResponse usage(String id){AiSecurityContext c=context(id);return new RunUsageResponse(inspection.usage(c.getTenant().getTenantId(),c.getWorkspace().getWorkspaceId(),id));}private List<RunInspectionItemResponse>items(String id,BiFunction<String,String,List<RunInspectionItem>>query){AiSecurityContext c=context(id);return query.apply(c.getTenant().getTenantId(),c.getWorkspace().getWorkspaceId()).stream().map(RunInspectionItemResponse::new).collect(Collectors.toList());}private AiSecurityContext context(String id){AiSecurityContext c=access.require(AiPermission.ADMIN);runs.find(c.getTenant().getTenantId(),c.getWorkspace().getWorkspaceId(),id).orElseThrow(()->new IllegalArgumentException("RUN_NOT_FOUND"));return c;}}
